<?php
use App\Http\Controllers\Academic\{AcademicSubjectController,AttendanceController,ClassroomJournalController,GradeController,ReportController,TeachingJournalController};use Illuminate\Support\Facades\Route;
Route::middleware(['auth','active','force-password-change'])->prefix('academic')->name('academic.')->group(function(){Route::get('attendance',[AttendanceController::class,'index'])->middleware('permission:academic-attendance.view')->name('attendance.index');Route::post('attendance',[AttendanceController::class,'store'])->middleware('permission:academic-attendance.manage')->name('attendance.store');Route::get('attendance/history',[AttendanceController::class,'history'])->middleware('permission:academic-attendance.view')->name('attendance.history');Route::get('grades',[GradeController::class,'index'])->middleware('permission:academic-grades.view')->name('grades.index');Route::post('grades',[GradeController::class,'store'])->middleware('permission:academic-grades.manage')->name('grades.store');Route::post('grades/subjects',[GradeController::class,'subject'])->middleware('permission:academic-subjects.manage')->name('grades.subjects.store');Route::resource('subjects',AcademicSubjectController::class)->only(['index','store','update'])->middleware('permission:academic-subjects.view');Route::post('teaching-journals/template',[TeachingJournalController::class,'uploadTemplate'])->middleware('permission:teaching-journals.manage')->name('teaching-journals.template.store');Route::get('teaching-journals/report/{format}',[TeachingJournalController::class,'report'])->whereIn('format',['docx','pdf'])->middleware('permission:teaching-journals.view')->name('teaching-journals.report');Route::resource('teaching-journals',TeachingJournalController::class)->middleware('permission:teaching-journals.view');Route::resource('classroom-journals',ClassroomJournalController::class)->except('destroy')->middleware('permission:classroom-journals.view');Route::get('reports',ReportController::class)->middleware('permission:academic-reports.view')->name('reports.index');});
